#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-25; prov histogram added 2026-10-26
"""One line per session of the night queue: what FISH extracted (vertices, trigger edges by evidence, joins, candidates, structural),
then one block per session with the evidence labels of every edge (from fish_tasks.json) and the model's provenance line.
Usage: python3 scripts/task4_summary.py [~/fish_traces/night_20261025_final] [--edges]"""
import collections, glob, json, os, re, sys
args = [a for a in sys.argv[1:] if not a.startswith('--')]
LD = args[0] if args else os.path.expanduser('~/fish_traces/night_20261025_final')
done = os.path.join(LD, 'pipelines_done.txt')
sessions = [l.strip() for l in open(done)] if os.path.exists(done) else []
fam_of = {}
for f in glob.glob(os.path.join(LD, 'task4*_*.log')):      # task4_<fam>.log (plan) / task4c_<fam>.log (queue4 as run)
    fam = os.path.basename(f)[:-4].split('_', 1)[1]
    for m in re.finditer(r'(fish_\d{8}_\d{6})', open(f, errors='ignore').read()): fam_of[m.group(1)] = fam
mp = os.path.join(LD, 'task4_sessions_map.txt')            # session -> family, written by task4_session_links_20261026.sh (authoritative)
if os.path.exists(mp):
    for line in open(mp):
        parts = line.split()
        if len(parts) == 2: fam_of[parts[0]] = parts[1]
runs = {}
rc = os.path.join(LD, 'task4c', 'runs.csv')
if os.path.exists(rc):
    for line in open(rc):
        p = line.strip().split(',')
        if len(p) == 6 and p[1] == 'lttng': runs[p[0]] = f'rc={p[3]}'
print(f"{'session':22s} {'family':20s} {'run':6s} {'cbs':>4s} {'trig':>5s} {'joins':>5s} {'struct':>6s} {'sampl':>5s} {'inact':>5s} {'cand':>5s} {'unpair':>6s}  edge evidence (kind:prov=n)")
blocks = []
for s in sessions:
    fam = fam_of.get(s, 'autoware')
    t = os.path.expanduser(f'~/fish_traces/analysis_{s}/fish_tasks.txt')
    j = os.path.expanduser(f'~/fish_traces/analysis_{s}/fish_tasks.json')
    if not os.path.exists(t): print(f'{s:22s} {fam:20s} {runs.get(fam, ""):6s} (no fish_tasks.txt)'); continue
    txt = open(t, errors='ignore').read()
    g = lambda pat, d='-': (re.search(pat, txt) or [None, d])[1]
    cbs = g(r'vertices: (\d+) callbacks'); trig = g(r'trigger edges with instances: (\d+)')
    joins = g(r'join edges: (\d+)'); struct = g(r'still structural \(no evidence\): (\d+)')
    hist = collections.Counter(); n_s = n_i = n_c = n_u = 0
    if os.path.exists(j):
        d = json.load(open(j))
        for task in d.get('tasks', []):
            for e in task.get('edges', []): hist[f"{e.get('kind')}:{e.get('prov')}"] += 1
        n_s, n_i, n_c, n_u = (len(d.get(k, [])) for k in ('sampled', 'inactive_edges', 'candidates', 'unpaired'))
    ev = ' '.join(f'{k}={v}' for k, v in sorted(hist.items(), key=lambda kv: -kv[1]))
    print(f'{s:22s} {fam:20s} {runs.get(fam, ""):6s} {cbs:>4s} {trig:>5s} {joins:>5s} {struct:>6s} {n_s:>5d} {n_i:>5d} {n_c:>5d} {n_u:>6d}  {ev}')
    sm = os.path.expanduser(f'~/fish_traces/analysis_{s}/summary.txt')
    prov = ''
    if os.path.exists(sm):
        m = re.search(r'provenance of derived quantities: ([^\n]*)', open(sm, errors='ignore').read())
        prov = m.group(1) if m else ''
    blocks.append((s, fam, prov))
heur = collections.Counter()
for s, fam, prov in blocks:
    print(f'  {s} {fam:18s} model: {prov}')
print()
print("evidence classes over all sessions (edges): exact:*/measured:*/container:*/pointer:*/stamp:*/by-construction:* are observed;"
      " inferred:* is a heuristic pairing (no identity record) — the programme requires those to become candidates or exact.")
